Prob061_2014_q4a.code:
// TopModule implements a single stage of a shift register.
// Logic:
// - If L (Load) is asserted, the stage loads the value of R.
// - Else if E (Enable) is asserted, the stage shifts in the value of w.
// - Otherwise, the stage maintains its current state.
// All operations occur on the positive edge of clk.

module TopModule (
    input  clk,
    input  w,
    input  R,
    input  E,
    input  L,
    output Q
);

    // Internal register to hold the state of the shift register stage
    reg q_reg;

    always @(posedge clk) begin
        if (L) begin
            // Load operation takes priority
            q_reg <= R;
        end else if (E) begin
            // Shift operation occurs if enabled and not loading
            q_reg <= w;
        end
        // Implicit else: q_reg <= q_reg; (Hold state)
    end

    // Assign the internal register to the output port
    assign Q = q_reg;

endmodule

