/*
 * Module: TopModule
 * Description: Combinational logic for a Moore state machine.
 * State Encoding (One-Hot):
 * A = 4'b0001
 * B = 4'b0010
 * C = 4'b0100
 * D = 4'b1000
 * 
 * Transition Table:
 * State | in=0 | in=1 | Out
 *   A   |  A   |  B   |  0
 *   B   |  C   |  B   |  0
 *   C   |  A   |  D   |  0
 *   D   |  C   |  B   |  1
 */

module TopModule (
    input        in,
    input  [3:0] state,
    output [3:0] next_state,
    output       out
);

    // State bit mapping for readability
    // state[0] = A, state[1] = B, state[2] = C, state[3] = D

    // Next State Logic Equations derived by inspection:
    // next_state[0] (A) is reached if:
    // (state == A && in == 0) || (state == C && in == 0)
    assign next_state[0] = (state[0] & ~in) | (state[2] & ~in);

    // next_state[1] (B) is reached if:
    // (state == A && in == 1) || (state == B && in == 1) || (state == D && in == 1)
    assign next_state[1] = (state[0] & in) | (state[1] & in) | (state[3] & in);

    // next_state[2] (C) is reached if:
    // (state == B && in == 0) || (state == D && in == 0)
    assign next_state[2] = (state[1] & ~in) | (state[3] & ~in);

    // next_state[3] (D) is reached if:
    // (state == C && in == 1)
    assign next_state[3] = (state[2] & in);

    // Output Logic:
    // out is 1 only when in state D
