module TopModule (
    input  clk,
    input  reset,
    output [4:0] q
);

    // Internal register to hold the LFSR state
    reg [4:0] lfsr_reg;

    // The output q is the current state of the LFSR
    assign q = lfsr_reg;

    // Galois LFSR Logic
    // Specification: 5-bit maximal-length Galois LFSR
    // Taps at bit positions 5 and 3.
    // In a Galois LFSR shifting right:
    // The LSB (q[0]) is the feedback bit.
    // If a bit position has a tap, the next value is (current_bit >> 1) XOR feedback.
    // Otherwise, it is just (current_bit >> 1).
    //
    // For a 5-bit register (indices 4 down to 0):
    // Bit 5 (the input to the MSB) is tapped: next_q[4] = q[0]
    // Bit 4: next_q[3] = q[4]
    // Bit 3: next_q[2] = q[3] ^ q[0]
    // Bit 2: next_q[1] = q[2]
    // Bit 1: next_q[0] = q[1]
    //
    // Note: "Taps at bit positions 5 and 3" usually refers to the 1-based 
    // position of the bits in the shift chain. 
    // Position 5 is the MSB (index 4), Position 3 is index 2.

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset to 1 (binary 00001)
            lfsr_reg <= 5'b00001;
        end else begin
            lfsr_reg <= {
                lfsr_reg[0],               // Tap at pos 5 (MSB)
                lfsr_reg[4],              // Pos 4
                lfsr_reg[3] ^ lfsr_reg[0], // Tap at pos 3
                lfsr_reg[2],              // Pos 2
                lfsr_reg[1]               // Pos 1
            };
        end
    end

endmodule

