module TopModule (
    input  logic [99:0] in,
    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    // (1) out_both: bit i and its neighbour to the left (i+1) are both '1'.
    // out_both[99] is 0 because it has no neighbour to the left.
    always_comb begin
        for (int i = 0; i < 100; i++) begin
            if (i == 99) begin
                out_both[i] = 1'b0;
            end else begin
                out_both[i] = in[i] & in[i+1];
            end
        end
    end

    // (2) out_any: bit i or its neighbour to the right (i-1) is '1'.
    // out_any[0] is 0 because it has no neighbour to the right.
    always_comb begin
        for (int i = 0; i < 100; i++) begin
            if (i == 0) begin
                out_any[i] = 1'b0;
            end else begin
                out_any[i] = in[i] | in[i-1];
            end
        end
    end

    // (3) out_different: bit i is different from its neighbour to the left.
    // Wrap around: in[99]'s neighbour to the left is in[0].
    always_comb begin
        for (int i = 0; i < 100; i++) begin
            if (i == 99) begin
                out_different[i] = in[i] ^ in[0];
