module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    // State definitions
    // State A: Waiting for s=1 to start the sequence
    // State B: 1st cycle of w check
    // State C: 2nd cycle of w check
    // State D: 3rd cycle of w check
    typedef enum logic [2:0] {
        STATE_A = 3'd0,
        STATE_B = 3'd1,
        STATE_C = 3'd2,
        STATE_D = 3'd3
    } state_t;

    state_t current_state, next_state;

    // Counters to track the number of 1s seen in the 3-cycle window
    reg [1:0] w_count;

    // State Transition Logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= STATE_A;
            w_count <= 2'd0;
        end else begin
            current_state <= next_state;

            // Update w_count based on current state and input w
            if (current_state == STATE_A) begin
                w_count <= 2'd0;
            end else if (current_state == STATE_B || current_state == STATE_C || current_state == STATE_D) begin
                if (current_state == STATE_D) begin
                    // Reset count for the next 3-cycle window
                    w_count <= (w) ? 2'd1 : 2'd0;
                end else begin
                    if (w) w_count <= w_count + 1'b1;
                end
            end
        end
    end

    // Next State Combinational Logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            STATE_A: begin
                if (s) next_state = STATE_B;
                else   next_state = STATE_A;
            end
            STATE_B: begin
                next_state = STATE_C;
            end
            STATE_C: begin
                next_state = STATE_D;
            end
            STATE_D: begin
                next_state = STATE_B;
            end
            default: next_state = STATE_A;
        endcase
    end

    // Output Logic
    // z is 1 in the clock cycle following the 3rd cycle of w check
    // if exactly two 1s were seen in those three cycles.
    always @(posedge clk) begin
        if (reset) begin
            z <= 1'b0;
        end else begin
            if (current_state == STATE_D) begin
                // We are currently in the 3rd cycle. 
                // The total count of 1s will be (w_count + current w).
                if ((w_count + w) == 2'd2) begin
                    z <= 1'b1;
                end else begin
                    z <= 1'b0;
                end
            end else begin
                z <= 1'b0;
            end
        end
    end

endmodule

