module TopModule (
    input  clk,
    input  in,
    input  reset,
    output logic [7:0] out_byte,
    output logic done
);

    // State definitions
    typedef enum logic [2:0] {
        IDLE    = 3'b000,
        START   = 3'b001,
        DATA    = 3'b010,
        STOP    = 3'b011,
        WAIT_1  = 3'b100
    } state_t;

    state_t state;
    logic [2:0] bit_cnt;
    logic [7:0] shift_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            bit_cnt   <= 3'b000;
            shift_reg <= 8'b0;
            out_byte  <= 8'b0;
            done      <= 1'b0;
        end else begin
            done <= 1'b0; // Default value

            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START;
                    end
                end

                START: begin
                    // We have detected the start bit (0). 
                    // Now we move to collect 8 data bits.
                    state   <= DATA;
                    bit_cnt <= 3'b000;
                end

                DATA: begin
                    // Shift in data bits (LSB first)
                    shift_reg <= {in, shift_reg[7:1]};
                    if (bit_cnt == 3'd7) begin
                        state   <= STOP;
                        bit_cnt <= 3'b000;
                    end else begin
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end

                STOP: begin
                    if (in == 1'b1) begin
                        // Stop bit is correct
                        out_byte <= shift_reg;
                        done     <= 1'b1;
                        state    <= IDLE;
                    end else begin
                        // Stop bit missing: wait until line is 1
                        state    <= WAIT_1;
                    end
                end

                WAIT_1: begin
                    if (in == 1'b1) begin
                        // Found a stop bit (or idle line), now we can look for next start bit
                        done  <= 1'b1; // Specification: "assert done each time it finds a stop bit"
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

