module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // State definitions
    // We need to track the walking direction even while falling.
    // States: 
    // 0: Walking Left
    // 1: Walking Right
    // 2: Falling (was walking left)
    // 3: Falling (was walking right)
    typedef enum logic [1:0] {
        WALK_L = 2'b00,
        WALK_R = 2'b01,
        FALL_L = 2'b10,
        FALL_R = 2'b11
    } state_t;

    state_t current_state, next_state;

    // State Transition Logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            WALK_L: begin
                if (!ground) begin
                    next_state = FALL_L;
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    // If bumped on both, spec says "still switch directions"
                    // Since we are walking left, bump_left triggers the switch.
                    next_state = WALK_R;
                end
            end
            WALK_R: begin
                if (!ground) begin
                    next_state = FALL_R;
                end else if (bump_right) begin
                    // Bumped on right -> walk left
                    next_state = WALK_L;
                end
            end
            FALL_L: begin
                if (ground) begin
                    next_state = WALK_L;
                end
                // Bumps are ignored while falling
            end
            FALL_R: begin
                if (ground) begin
                    next_state = WALK_R;
                end
                // Bumps are ignored while falling
            end
            default: next_state = WALK_L;
        endcase
    end

    // Special case for "bumped on both sides" while walking:
    // The spec says: "If it's bumped on both sides at the same time, it will still switch directions."
    // In WALK_L, if bump_left=1 and bump_right=1, it should go to WALK_R.
    // In WALK_R, if bump_left=1 and bump_right=1, it should go to WALK_L.
    // The logic above handles this: 
    // In WALK_L, bump_left=1 triggers WALK_R regardless of bump_right.
    // However, if bump_right=1 but bump_left=0, it stays WALK_L.
    // Wait, the spec says: "If it's bumped on the right... it will walk left."
    // Let's refine the transition for WALK_L and WALK_R to handle both bumps.

    /* Refined Transition Logic */
    always_comb begin
        next_state = current_state;
        case (current_state)
            WALK_L: begin
                if (!ground) begin
                    next_state = FALL_L;
                end else begin
                    if (bump_left && !bump_right) next_state = WALK_R;
                    else if (!bump_left && bump_right) next_state = WALK_L;
                    else if (bump_left && bump_right) next_state = WALK_R; // Switch direction
                end
            end
            WALK_R: begin
                if (!ground) begin
                    next_state = FALL_R;
                end else begin
                    if (bump_right && !bump_left) next_state = WALK_L;
                    else if (!bump_right && bump_left) next_state = WALK_R;
                    else if (bump_right && bump_left) next_state = WALK_L; // Switch direction
                end
            end
            FALL_L: begin
                if (ground) next_state = WALK_L;
            end
            FALL_R: begin
                if (ground) next_state = WALK_R;
            end
            default: next_state = WALK_L;
        endcase
    end

    // Sequential Logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_L;
        end else begin
            current_state <= next_state;
        end
    end

    // Moore Output Logic
    assign walk_left  = (current_state == WALK_L);
    assign walk_right = (current_state == WALK_R);
    assign aaah       = (current_state == FALL_L || current_state == FALL_R);

endmodule

