module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);

    // State definitions
    typedef enum reg [3:0] {
        S_IDLE,      // Searching for '1'
        S_1,         // Found '1'
        S_11,        // Found '11'
        S_110,       // Found '110'
        S_SHIFT,     // Found '1101', shifting in 4 bits
        S_COUNT,     // Waiting for counters to finish
        S_DONE       // Notifying user and waiting for ack
    } state_t;

    state_t state, next_state;
    reg [2:0] shift_count;

    // State Transition Logic
    always @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            shift_count <= 3'd0;
        end else begin
            state <= next_state;

            // Handle shift counter increment
            if (state == S_SHIFT) begin
                shift_count <= shift_count + 1'b1;
            end else begin
                shift_count <= 3'd0;
            end
        end
    end

    // Next State Logic
    always @(*) begin
        next_state = state;
        case (state)
            S_IDLE: begin
                if (data) next_state = S_1;
                else      next_state = S_IDLE;
            end
            S_1: begin
                if (data) next_state = S_11;
                else      next_state = S_IDLE;
            end
            S_11: begin
                if (data) next_state = S_11;
                else      next_state = S_110;
            end
            S_110: begin
                if (data) next_state = S_SHIFT;
                else      next_state = S_IDLE;
            end
            S_SHIFT: begin
                // Shift for exactly 4 clock cycles (0, 1, 2, 3)
                if (shift_count == 3'd3) begin
                    next_state = S_COUNT;
                end else begin
                    next_state = S_SHIFT;
                end
            end
            S_COUNT: begin
                if (done_counting) next_state = S_DONE;
                else               next_state = S_COUNT;
            end
            S_DONE: begin
                if (ack) next_state = S_IDLE;
                else     next_state = S_DONE;
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output Logic
    always @(*) begin
        shift_ena = 1'b0;
        counting  = 1'b0;
        done      = 1'b0;

        case (state)
            S_SHIFT: shift_ena = 1'b1;
            S_COUNT: counting  = 1'b1;
            S_DONE:  done      = 1'b1;
            default: ; 
        endcase
    end

endmodule

